import type { LessonContent } from './types';

function bi(day: number, topic: string, topicName: string, title: string, obj: string[], steps: string[], hint: string, hintCode: string, solDesc: string, solCode: string, success: string[], takeaway: string): LessonContent {
  return { topicSlug: topic, topicName, domainSlug: 'business-intelligence', dayNumber: day, title, duration: 47, objectives: obj, steps: steps.map(s => ({ instruction: s })), hint: { description: hint, code: hintCode }, fullSolution: { description: solDesc, code: solCode }, successCriteria: success, keyTakeaway: takeaway };
}

export const biLessons: LessonContent[] = [
  bi(1,'dashboard-design','Dashboard Design','Dashboard Layout Principles',['Understand visual hierarchy and F-pattern reading','Design a wireframe for a KPI dashboard'],['Identify your target audience and their top 3 questions','List the 5 most critical KPIs','Sketch a 3-column grid layout','Place most important KPI top-left (F-pattern)','Group related metrics into sections','Add a date filter and title bar','Review: can someone get the main message in 5 seconds?'],'Use a 3-column grid with the most important metric top-left. F-pattern reading means users scan left-to-right, then down.','layout = {\n    "row1": ["Revenue YTD", "Margin %", "Active Users"],\n    "row2": ["Revenue Trend", "Top Products"],\n}\nfor row, widgets in layout.items():\n    print(row + ": " + ", ".join(widgets))','Complete Plotly Dash layout with KPI grid.','import dash\nfrom dash import html, dcc\nimport plotly.graph_objects as go\n\napp = dash.Dash(__name__)\nkpis = [\n    {"label": "Revenue YTD", "value": "2.4M", "delta": "+12%"},\n    {"label": "Gross Margin", "value": "68%", "delta": "+3%"},\n    {"label": "Active Users", "value": "14,200", "delta": "-2%"},\n]\n\ndef make_card(kpi):\n    color = "#2a9d8f" if "+" in kpi["delta"] else "#e63946"\n    return html.Div([\n        html.H4(kpi["label"], style={"color": "#8899aa"}),\n        html.H2(kpi["value"]),\n        html.Span(kpi["delta"], style={"color": color, "fontWeight": "bold"}),\n    ], style={"background": "#142a3b", "padding": "20px", "borderRadius": "12px"})\n\napp.layout = html.Div([\n    html.H1("Executive Dashboard"),\n    html.Div([make_card(k) for k in kpis],\n        style={"display": "grid", "gridTemplateColumns": "repeat(3,1fr)", "gap": "16px"}),\n    dcc.Graph(figure=go.Figure(\n        go.Scatter(x=["Jan","Feb","Mar","Apr"], y=[100,120,115,140], mode="lines+markers")\n    ).update_layout(title="Revenue Trend", template="plotly_dark"))\n])\n\nif __name__ == "__main__":\n    app.run(debug=True)',['Dashboard has 3-column KPI row at top','Most important metric top-left','Main insight visible in 5 seconds','Date context visible without scrolling'],'Great dashboards answer the viewer\'s top question before they ask it.'),
  bi(2,'dashboard-design','Dashboard Design','Chart Type Selection Framework',['Match data types to chart types','Apply the chart selection decision tree'],['List 5 data relationships in your dataset','Identify data type: categorical, time-series, numeric','Apply: categorical=bar, time=line, correlation=scatter','Create one chart of each type','Evaluate clarity of each','Replace pie charts with >6 slices','Document rationale'],'Decision tree: comparison=bar, trend=line, part-of-whole=pie/treemap, relationship=scatter, distribution=histogram.','import matplotlib.pyplot as plt\nimport numpy as np\n\nfig, axes = plt.subplots(2, 2, figsize=(10, 8))\ncats = ["Q1", "Q2", "Q3", "Q4"]\nvals = [23, 45, 56, 78]\naxes[0,0].bar(cats, vals); axes[0,0].set_title("Bar: Comparison")\naxes[0,1].plot(cats, vals, "o-"); axes[0,1].set_title("Line: Trend")\naxes[1,0].pie(vals, labels=cats); axes[1,0].set_title("Pie: Composition")\naxes[1,1].scatter(np.random.randn(50), np.random.randn(50))\naxes[1,1].set_title("Scatter: Correlation")\nplt.tight_layout(); plt.savefig("chart_types.png")','Chart selection guide with all 5 types.','import pandas as pd\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nnp.random.seed(42)\ncategories = ["Electronics", "Clothing", "Food", "Services", "Other"]\ncat_values = [340, 280, 190, 150, 40]\n\nfig, axes = plt.subplots(2, 3, figsize=(15, 10))\nfig.suptitle("Chart Type Selection Guide", fontsize=16)\n\naxes[0,0].barh(categories, cat_values, color="#457b9d")\naxes[0,0].set_title("Bar: Compare Categories")\n\nmonths = pd.date_range("2025-01", periods=12, freq="M")\nrevenue = np.cumsum(np.random.normal(50, 15, 12)) + 500\naxes[0,1].plot(months, revenue, color="#2a9d8f", linewidth=2)\naxes[0,1].set_title("Line: Trend Over Time")\n\nx = np.random.normal(50, 10, 100)\naxes[0,2].scatter(x, x*0.8 + np.random.normal(0, 5, 100), alpha=0.6, color="#e63946")\naxes[0,2].set_title("Scatter: Correlation")\n\naxes[1,0].hist(np.random.normal(100, 15, 500), bins=25, color="#a8dadc")\naxes[1,0].set_title("Histogram: Distribution")\n\nleft = 0\ncolors = ["#264653","#2a9d8f","#e9c46a","#f4a261","#e76f51"]\nfor i, (cat, val) in enumerate(zip(categories, cat_values)):\n    w = val / sum(cat_values) * 100\n    axes[1,1].barh(["Revenue"], [w], left=left, color=colors[i], label=cat)\n    left += w\naxes[1,1].legend(fontsize=8)\naxes[1,1].set_title("Stacked: Composition")\n\naxes[1,2].axis("off")\nplt.tight_layout()\nplt.savefig("chart_guide.png", dpi=150)',['Created 4+ chart types','No pie with >5 slices','Clear titles on each chart','Rationale documented'],'The right chart makes the insight obvious.'),
  bi(3,'dashboard-design','Dashboard Design','Interactive Dashboard with Plotly Dash',['Build a multi-chart interactive dashboard','Implement dropdown callbacks'],['Install: pip install dash plotly pandas','Create layout with dropdown and 3 charts','Add callback updating charts on filter change','Add date range picker','Apply dark theme','Test all interactions','Run at localhost:8050'],'Use dcc.Dropdown for filters and @app.callback to update dcc.Graph figures.','import dash\nfrom dash import dcc, html, callback, Input, Output\nimport plotly.express as px\n\napp = dash.Dash(__name__)\ndf = px.data.gapminder()\napp.layout = html.Div([\n    dcc.Dropdown(id="cont", options=[{"label": c, "value": c}\n        for c in df["continent"].unique()], value="Europe"),\n    dcc.Graph(id="chart"),\n])\n\n@callback(Output("chart", "figure"), Input("cont", "value"))\ndef update(cont):\n    return px.scatter(df[df.continent==cont], x="gdpPercap", y="lifeExp",\n        size="pop", color="country", template="plotly_dark")','Full Dash app with 3 linked charts.','import dash\nfrom dash import dcc, html, callback, Input, Output\nimport plotly.express as px\nimport pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\ndates = pd.date_range("2025-01-01", periods=365, freq="D")\nregions = ["North", "South", "East", "West"]\ndata = []\nfor region in regions:\n    base = np.random.randint(80, 150)\n    sales = base + np.cumsum(np.random.normal(0.5, 3, 365))\n    for d, s in zip(dates, sales):\n        data.append({"date": d, "region": region, "sales": max(0, s)})\ndf = pd.DataFrame(data)\n\napp = dash.Dash(__name__)\napp.layout = html.Div([\n    html.H1("Sales Dashboard"),\n    dcc.Dropdown(id="region",\n        options=[{"label": "All", "value": "All"}] +\n            [{"label": r, "value": r} for r in regions], value="All"),\n    html.Div([dcc.Graph(id="trend"), dcc.Graph(id="bar")],\n        style={"display": "flex"}),\n    dcc.Graph(id="heat"),\n])\n\n@callback(\n    [Output("trend","figure"), Output("bar","figure"), Output("heat","figure")],\n    Input("region","value"))\ndef update(region):\n    f = df if region=="All" else df[df.region==region]\n    d = f.groupby("date")["sales"].sum().reset_index()\n    trend = px.line(d, x="date", y="sales", template="plotly_dark")\n    by_r = f.groupby("region")["sales"].sum().reset_index()\n    bar = px.bar(by_r, x="region", y="sales", color="region", template="plotly_dark")\n    fc = f.copy(); fc["month"] = fc["date"].dt.month_name()\n    fc["dow"] = fc["date"].dt.day_name()\n    p = fc.groupby(["dow","month"])["sales"].mean().reset_index()\n    heat = px.density_heatmap(p, x="month", y="dow", z="sales", template="plotly_dark")\n    return trend, bar, heat\n\nif __name__ == "__main__":\n    app.run(debug=True, port=8050)',['Runs at localhost:8050','Dropdown updates all 3 charts','Consistent dark theme','Heatmap shows patterns'],'Callbacks cascade updates to every connected output.'),
  bi(4,'dashboard-design','Dashboard Design','Color Theory and Accessibility',['Apply WCAG contrast standards','Create colorblind-safe palette'],['Audit color contrast (text on background)','Test: minimum 4.5:1 for normal text','Replace red/green with blue/orange','Choose sequential palette for ordered data','Choose diverging palette for midpoint data','Calculate data-ink ratio','Remove non-data decorations'],'Use ColorBrewer palettes. Sequential: Blues. Diverging: RdBu. Always test with colorblind simulator.','def contrast_ratio(l1, l2):\n    lighter, darker = max(l1, l2), min(l1, l2)\n    return (lighter + 0.05) / (darker + 0.05)\n\nbg = 0.027  # dark navy\ntext = 0.95  # near white\nratio = contrast_ratio(text, bg)\nprint("Contrast: {:.1f}:1".format(ratio))\nprint("WCAG AA: {}".format("PASS" if ratio >= 4.5 else "FAIL"))','Accessible palette generator with contrast checking.','import matplotlib.pyplot as plt\nimport matplotlib.colors as mcolors\n\ndef hex_to_lum(hex_color):\n    rgb = mcolors.hex2color(hex_color)\n    ch = []\n    for c in rgb:\n        c = c/12.92 if c <= 0.03928 else ((c+0.055)/1.055)**2.4\n        ch.append(c)\n    return 0.2126*ch[0] + 0.7152*ch[1] + 0.0722*ch[2]\n\ndef check(fg, bg):\n    l1, l2 = hex_to_lum(fg), hex_to_lum(bg)\n    return (max(l1,l2)+0.05)/(min(l1,l2)+0.05)\n\npalette = {"Primary":"#457b9d","Success":"#2a9d8f","Warning":"#e9c46a",\n    "Danger":"#e76f51","Info":"#a8dadc","Neutral":"#8899aa"}\nbg = "#0b1d2a"\n\nprint("=== Palette Contrast Check ===")\nfig, ax = plt.subplots(figsize=(8,4))\nfor i, (name, color) in enumerate(palette.items()):\n    r = check(color, bg)\n    s = "AA" if r >= 4.5 else "FAIL"\n    ax.barh(i, r, color=color)\n    ax.text(r+0.2, i, "{:.1f}:1 [{}]".format(r, s), va="center", color="white")\n    print("  {} ({}): {:.1f}:1 [{}]".format(name, color, r, s))\nax.set_yticks(range(len(palette)))\nax.set_yticklabels(palette.keys(), color="white")\nax.axvline(x=4.5, color="#e63946", linestyle="--", label="WCAG AA")\nax.set_facecolor("#0b1d2a"); fig.set_facecolor("#0b1d2a")\nplt.tight_layout()\nplt.savefig("accessibility.png", dpi=150, facecolor="#0b1d2a")',['All text passes WCAG AA','No red/green only encoding','Data-ink ratio > 0.7','Works in colorblind simulator'],'Accessible design is a quality signal.'),
  bi(5,'dashboard-design','Dashboard Design','Dashboard Performance Review',['Evaluate using Tufte principles','Remove chartjunk'],['Select a dashboard','List every visual element','Ask: does each help understand data?','Remove decorative elements','Replace 3D with 2D','Add direct labels over legends','Compare before/after'],'Tufte data-ink ratio = data ink / total ink. Maximize by removing gridlines, borders, backgrounds.','total = 45\ndata = 28\nratio = data / total\nprint("Data-ink ratio: {:.2f}".format(ratio))\nprint("Target: > 0.75")\nfor item in ["3D effects","Gradient fills","Dense gridlines","Redundant legends"]:\n    print("  Remove: " + item)','Before/after dashboard cleanup.','import matplotlib.pyplot as plt\n\nmonths = ["Jan","Feb","Mar","Apr","May","Jun"]\nrev = [120, 135, 128, 142, 155, 148]\n\nfig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 5))\n\n# Before\nax1.bar(months, rev, color="skyblue", edgecolor="navy", linewidth=2)\nax1.set_title("BEFORE", fontsize=14, fontweight="bold")\nax1.grid(True, linewidth=1, color="gray", alpha=0.7)\nax1.set_facecolor("#f0f0f0")\nax1.set_ylabel("Revenue")\n\n# After\nax2.bar(months, rev, color="#2a9d8f", width=0.6)\nfor i, v in enumerate(rev):\n    ax2.text(i, v+1, "{}K".format(v), ha="center", fontsize=10, color="#f8f9fb")\nax2.set_title("AFTER", fontsize=14, fontweight="bold", color="#f8f9fb")\nax2.set_facecolor("#0b1d2a")\nax2.spines["top"].set_visible(False)\nax2.spines["right"].set_visible(False)\nax2.spines["left"].set_visible(False)\nax2.tick_params(colors="#a8dadc")\nax2.set_yticks([]); ax2.grid(False)\nfig.patch.set_facecolor("#091722")\nplt.tight_layout()\nplt.savefig("tufte.png", dpi=150, facecolor="#091722")\nprint("Improved from ~0.4 to ~0.85")',['Removed 5+ chartjunk elements','Data-ink improved 0.2+','Direct labels over legends','Clear before/after improvement'],'Less is more — every removed element makes data louder.'),
  bi(1,'kpi-metrics','KPI Metrics','What Makes a Good KPI',['Apply SMART framework','Distinguish leading vs lagging'],['List top 5 business goals','Brainstorm 3 metrics per goal','Apply SMART test','Classify leading vs lagging','Eliminate vanity metrics','Select 1 primary KPI per goal','Document: name, formula, target, owner'],'If you cannot act on it, it is not a KPI.','kpis = [\n    {"name": "MRR", "type": "lagging", "target": "500K"},\n    {"name": "Pipeline Coverage", "type": "leading", "target": "3x"},\n]\nfor k in kpis:\n    print("{} ({}): target {}".format(k["name"], k["type"], k["target"]))','KPI framework with SMART validation.','import pandas as pd\n\ndf = pd.DataFrame([\n    {"goal":"Grow Revenue","kpi":"MRR Growth","type":"lagging","target":"10% MoM","actionable":True},\n    {"goal":"Grow Revenue","kpi":"Pipeline Coverage","type":"leading","target":"3x","actionable":True},\n    {"goal":"Reduce Churn","kpi":"Net Retention","type":"lagging","target":">110%","actionable":True},\n    {"goal":"Reduce Churn","kpi":"Health Score","type":"leading","target":">80","actionable":True},\n    {"goal":"Efficiency","kpi":"CAC Payback","type":"lagging","target":"<12mo","actionable":True},\n])\nprint("=== KPI Framework ===")\nprint(df[["goal","kpi","type","target"]].to_string(index=False))\nprint("Leading: {}  Lagging: {}".format((df.type=="leading").sum(), (df.type=="lagging").sum()))',['Each KPI passes SMART','Mix of leading and lagging','No vanity metrics','Definitions complete'],'A good KPI tells you what to do when it turns red.'),
  bi(2,'kpi-metrics','KPI Metrics','Financial KPIs',['Calculate core financial KPIs','Interpret LTV/CAC ratio'],['Load revenue and cost data','Calculate Revenue Growth Rate','Calculate Gross Margin','Calculate CAC','Calculate LTV','Compute LTV/CAC (healthy >3)','Create summary with traffic lights'],'LTV/CAC > 3 means you earn 3x what you spend acquiring a customer.','revenue = [100, 112, 125, 118, 140]\ncogs = [35, 38, 42, 40, 45]\ngrowth = [(revenue[i]-revenue[i-1])/revenue[i-1]*100 for i in range(1,len(revenue))]\nmargin = [(r-c)/r*100 for r,c in zip(revenue, cogs)]\nprint("Avg Growth: {:.1f}%".format(sum(growth)/len(growth)))\nprint("LTV/CAC: {:.1f}x".format((85*0.65*24)/350))','Complete financial KPI calculator.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\ndata = pd.DataFrame({\n    "month": pd.date_range("2025-01", periods=12, freq="M"),\n    "revenue": np.cumsum(np.random.normal(15, 3, 12)) + 200,\n    "cogs": np.cumsum(np.random.normal(5, 1, 12)) + 70,\n    "mktg": np.random.uniform(20, 40, 12),\n    "new_cust": np.random.randint(30, 80, 12),\n})\ndata["margin"] = (data["revenue"]-data["cogs"])/data["revenue"]*100\ndata["growth"] = data["revenue"].pct_change()*100\ndata["cac"] = data["mktg"]/data["new_cust"]*1000\narpu, lifespan = 85, 24\navg_margin = data["margin"].mean()/100\nltv = arpu * avg_margin * lifespan\navg_cac = data["cac"].mean()\n\nprint("=== Financial KPIs ===")\nprint("Revenue: {:.0f}K".format(data["revenue"].iloc[-1]))\nprint("Growth: {:.1f}%".format(data["growth"].mean()))\nprint("Margin: {:.1f}%".format(data["margin"].mean()))\nprint("CAC: {:.0f}".format(avg_cac))\nprint("LTV: {:.0f}".format(ltv))\nprint("LTV/CAC: {:.1f}x {}".format(ltv/avg_cac, "OK" if ltv/avg_cac>3 else "LOW"))',['5+ financial KPIs calculated','LTV/CAC computed and interpreted','Traffic lights applied','Formulas documented'],'LTV/CAC is the single most important ratio for sustainable growth.'),
  bi(3,'kpi-metrics','KPI Metrics','Operational KPIs',['Calculate OEE components','Track throughput and cycle time'],['Define: throughput, cycle time, utilization, defect rate','Load production data','Calculate throughput','Calculate cycle time','Calculate OEE = Avail x Perf x Quality','Identify bottleneck','Create OEE breakdown chart'],'OEE = Availability x Performance x Quality. World-class is 85%.','a, p, q = 0.90, 0.85, 0.95\noee = a * p * q\nprint("OEE: {:.1%}".format(oee))\nprint("Bottleneck: Performance ({:.0%})".format(p))','Full OEE calculator.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\nshifts = pd.DataFrame({\n    "shift": range(1, 31), "planned": 480,\n    "downtime": np.random.randint(15, 90, 30),\n    "ideal_cycle": 30,\n    "actual_units": np.random.randint(600, 900, 30),\n    "defects": np.random.randint(5, 40, 30),\n})\nshifts["run"] = shifts["planned"] - shifts["downtime"]\nshifts["avail"] = shifts["run"] / shifts["planned"]\nshifts["ideal_units"] = shifts["run"] * 60 / shifts["ideal_cycle"]\nshifts["perf"] = shifts["actual_units"] / shifts["ideal_units"]\nshifts["good"] = shifts["actual_units"] - shifts["defects"]\nshifts["qual"] = shifts["good"] / shifts["actual_units"]\nshifts["oee"] = shifts["avail"] * shifts["perf"] * shifts["qual"]\n\nprint("=== OEE Summary ===")\nprint("Availability: {:.1%}".format(shifts["avail"].mean()))\nprint("Performance:  {:.1%}".format(shifts["perf"].mean()))\nprint("Quality:      {:.1%}".format(shifts["qual"].mean()))\nprint("OEE:          {:.1%}".format(shifts["oee"].mean()))\nc = {"Avail":shifts["avail"].mean(),"Perf":shifts["perf"].mean(),"Qual":shifts["qual"].mean()}\nprint("Bottleneck: {}".format(min(c, key=c.get)))',['OEE = product of 3 components','Bottleneck identified','Throughput computed','Best/worst shift analyzed'],'Fix the lowest OEE component for the biggest gain.'),
  bi(4,'kpi-metrics','KPI Metrics','Building a KPI Scorecard',['Automate traffic-light scoring','Export styled scorecard'],['Define 8+ KPIs with thresholds','Pull actuals into DataFrame','Assign RAG status','Create summary table','Style with conditional formatting','Export to Excel','Add timestamp'],'Use pandas.style for conditional cell coloring.','import pandas as pd\nkpis = pd.DataFrame({\n    "KPI": ["Revenue Growth","Margin","NPS","Churn"],\n    "Actual": [8.5, 62, 45, 3.2],\n    "Target": [10, 65, 50, 2.5],\n})\nkpis["Status"] = kpis.apply(lambda r: "GREEN" if r.Actual>=r.Target*0.95 else "RED", axis=1)\nprint(kpis.to_string(index=False))','Automated scorecard with Excel export.','import pandas as pd\nfrom datetime import datetime\n\ncfg = [\n    {"kpi":"Revenue Growth","actual":8.5,"target":10,"unit":"%","green":9,"yellow":7,"up":True},\n    {"kpi":"Gross Margin","actual":64.2,"target":65,"unit":"%","green":63,"yellow":58,"up":True},\n    {"kpi":"NPS","actual":52,"target":50,"unit":"pts","green":48,"yellow":40,"up":True},\n    {"kpi":"Churn","actual":2.8,"target":2.5,"unit":"%","green":2.7,"yellow":3.5,"up":False},\n    {"kpi":"CAC Payback","actual":11,"target":12,"unit":"mo","green":12,"yellow":15,"up":False},\n    {"kpi":"LTV/CAC","actual":3.4,"target":3.0,"unit":"x","green":2.8,"yellow":2.0,"up":True},\n]\n\ndef rag(r):\n    if r["up"]:\n        return "GREEN" if r["actual"]>=r["green"] else "YELLOW" if r["actual"]>=r["yellow"] else "RED"\n    else:\n        return "GREEN" if r["actual"]<=r["green"] else "YELLOW" if r["actual"]<=r["yellow"] else "RED"\n\ndf = pd.DataFrame(cfg)\ndf["status"] = df.apply(rag, axis=1)\ndf["vs%"] = ((df["actual"]-df["target"])/df["target"]*100).round(1)\n\nprint("=== Scorecard {} ===".format(datetime.now().strftime("%Y-%m-%d")))\nfor _, r in df.iterrows():\n    icon = {"GREEN":"[OK]","YELLOW":"[!!]","RED":"[XX]"}[r["status"]]\n    print("  {} {}: {}{} (target {}{}, {:+.1f}%)".format(icon,r["kpi"],r["actual"],r["unit"],r["target"],r["unit"],r["vs%"]))\ndf[["kpi","actual","target","status","vs%"]].to_excel("scorecard.xlsx",index=False)\nprint("Exported scorecard.xlsx")',['6+ KPIs with RAG status','Thresholds defined','Excel export works','vs-target % included'],'Automated scorecards turn tracking from a chore into always-on monitoring.'),
  bi(5,'kpi-metrics','KPI Metrics','KPI Storytelling',['Turn numbers into narratives','Apply the so-what test'],['Take your scorecard','Write so-what for each RED/YELLOW','Structure: what happened, why, what to do','Write 3-sentence executive summary','Add comparisons vs prior period','Remove jargon','Practice 15-second explanation'],'Lead with conclusion, not data.','def narrate(name, actual, target, prior, unit="%"):\n    vs = (actual-target)/target*100\n    trend = "up" if actual>prior else "down"\n    status = "on track" if abs(vs)<5 else "behind"\n    return "{} is {} at {}{} ({} from {}{})".format(name,status,actual,unit,trend,prior,unit)\n\nprint(narrate("Margin", 64.2, 65, 62.1))\nprint(narrate("Churn", 3.0, 2.5, 2.8))','Automated KPI narrative generator.','import pandas as pd\n\nkpis = pd.DataFrame([\n    {"kpi":"Revenue","current":2.4,"prior":2.1,"target":2.5,"unit":"M","up":True},\n    {"kpi":"Margin","current":64.2,"prior":62.1,"target":65,"unit":"%","up":True},\n    {"kpi":"Churn","current":3.0,"prior":2.8,"target":2.5,"unit":"%","up":False},\n    {"kpi":"NPS","current":52,"prior":48,"target":50,"unit":"pts","up":True},\n])\n\ndef narrate(row):\n    dt = (row["current"]-row["target"])/row["target"]*100\n    dp = (row["current"]-row["prior"])/row["prior"]*100\n    improving = (dp>0)==row["up"]\n    on_track = (dt>=0)==row["up"]\n    d = "up" if dp>0 else "down"\n    what = "{} at {}{}".format(row["kpi"],row["current"],row["unit"])\n    ctx = "{} {:.0f}% from {}{}".format(d,abs(dp),row["prior"],row["unit"])\n    action = "On track." if on_track else "Needs attention."\n    return "{} ({}). {}".format(what, ctx, action)\n\nprint("=== KPI Narrative ===\\n")\nfor _, r in kpis.iterrows():\n    print(narrate(r))\nprint("\\n=== Summary ===")\nprint("Revenue growing but churn threatens retention. Invest in CS.")',['Every metric has so-what','Plain language','Summary <=3 sentences','Prior period comparison'],'Data says what happened — narrative says what to do.'),
  bi(1,'etl','ETL Processes','ETL Fundamentals',['Understand Extract-Transform-Load','Identify sources and destinations'],['Draw: sources->extract->transform->load->dest','List 3 extract sources','List 5 transforms','List 2 load patterns','Add quality checks','Write skeleton with 3 functions'],'ETL: Extract (pull), Transform (clean), Load (write). Validate between stages.','def extract(): return [{"name":"Alice","sales":100},{"name":"Bob","sales":None}]\ndef transform(data): return [r for r in data if r["sales"] is not None]\ndef load(data): print("Loaded {} records".format(len(data)))\n\nraw = extract(); clean = transform(raw); load(clean)','Complete ETL pipeline with logging.','import pandas as pd\nimport logging\nfrom datetime import datetime\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")\nlog = logging.getLogger("etl")\n\ndef extract():\n    df = pd.DataFrame({"id":range(100),"name":["C_{}".format(i) for i in range(100)],\n        "revenue":[50+i*2.5 for i in range(100)],"region":["N","S","E","W"]*25})\n    log.info("Extracted %d rows", len(df)); return df\n\ndef transform(df):\n    n = len(df); df = df.drop_duplicates("id"); df = df.dropna(subset=["revenue"])\n    df["email"] = df["name"].str.lower() + "@co.com"\n    df["tier"] = pd.cut(df["revenue"],bins=[0,100,200,999],labels=["S","M","L"])\n    log.info("Transform: %d -> %d", n, len(df)); return df\n\ndef load(df):\n    df.to_csv("out.csv", index=False)\n    log.info("Loaded %d rows", len(df)); return len(df)\n\nstart = datetime.now()\ncount = load(transform(extract()))\nlog.info("Done: %d rows in %.2fs", count, (datetime.now()-start).total_seconds())',['3 distinct functions','Each logs row counts','3+ transforms applied','Runs end-to-end'],'Reliable ETL is boring by design.'),
  bi(2,'etl','ETL Processes','Data Extraction',['Extract from CSV, SQLite, API','Handle errors'],['Read CSV with pandas','Query SQLite','Call REST API with pagination','Add error handling','Validate: row counts, types','Log metadata'],'Use na_values=["","NA","null"] for CSVs. Check status_code for APIs.','import pandas as pd\nimport sqlite3\n\ndf = pd.DataFrame({"id":[1,2,3],"name":["A","B","C"]})\nprint("CSV: {} rows".format(len(df)))\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE t (id INT)")\nconn.execute("INSERT INTO t VALUES (1)")\nprint("SQL: {} rows".format(pd.read_sql("SELECT * FROM t",conn).shape[0]))','Multi-source extractor.','import pandas as pd\nimport sqlite3\n\ndef extract_csv(path):\n    try:\n        df = pd.read_csv(path, na_values=["","NA"])\n        print("[CSV] {} rows from {}".format(len(df), path)); return df\n    except: print("[CSV] Error"); return pd.DataFrame()\n\ndef extract_sql(db, query):\n    try:\n        conn = sqlite3.connect(db)\n        df = pd.read_sql(query, conn); conn.close()\n        print("[SQL] {} rows".format(len(df))); return df\n    except: print("[SQL] Error"); return pd.DataFrame()\n\ndef extract_api(url, pages=3):\n    data = []\n    for p in range(pages):\n        data.extend([{"id":i,"val":i*10} for i in range(p*10,(p+1)*10)])\n    print("[API] {} records".format(len(data)))\n    return pd.DataFrame(data)\n\ncsv = extract_csv("missing.csv")\napi = extract_api("https://example.com")\nprint("Total: {}".format(len(csv)+len(api)))',['2+ source types','Errors logged not crashed','Row counts reported','Pagination handled'],'Extract defensively — every source will eventually fail.'),
  bi(3,'etl','ETL Processes','Data Transformation',['Clean messy data','Build reusable pipeline'],['Load messy data','Remove duplicates','Handle nulls','Normalize dates','Standardize text','Derive columns','Validate output'],'Chain with df.pipe(). Keeps steps isolated and testable.','import pandas as pd\n\ndef clean(df):\n    df = df.dropna(subset=["id","email"])\n    df["phone"] = df["phone"].fillna("N/A")\n    return df\n\ndef normalize(df):\n    df["email"] = df["email"].str.lower().str.strip()\n    return df','Full transform pipeline with validation.','import pandas as pd\nimport numpy as np\n\nnp.random.seed(42)\ndf = pd.DataFrame({"id":list(range(200))+[0,1],\n    "name":["  C_{} ".format(i) for i in range(200)]+["C_0","C_1"],\n    "email":["c{}@EX.COM ".format(i) for i in range(200)]+["c0@ex.com","c1@ex.com"],\n    "revenue":list(np.random.uniform(10,500,200))+[100,200],\n    "region":list(np.random.choice(["North","south","EAST",None],200))+["N","S"]})\ndf.loc[5,"revenue"] = None\n\nprint("Raw: {} rows".format(len(df)))\ndf = df.drop_duplicates("id",keep="first")\ndf = df.dropna(subset=["id","email"])\ndf["revenue"] = df["revenue"].fillna(df["revenue"].median())\ndf["region"] = df["region"].fillna("Unknown")\ndf["email"] = df["email"].str.lower().str.strip()\ndf["name"] = df["name"].str.strip().str.title()\ndf["region"] = df["region"].str.title()\ndf["tier"] = pd.cut(df["revenue"],bins=[0,100,250,999],labels=["S","M","L"])\n\nassert df["id"].is_unique\nassert df["email"].notna().all()\nprint("Clean: {} rows".format(len(df)))\nprint(df.head(5).to_string(index=False))',['Duplicates removed','No nulls in required fields','Text normalized','2+ derived columns'],'Clean data is the foundation of trustworthy analytics.'),
  bi(4,'etl','ETL Processes','Data Loading',['Load into SQLite with upsert','Validate and handle errors'],['Create destination table','Insert in batches','Use INSERT OR REPLACE','Validate row counts','Add load timestamp','Test rollback'],'Wrap inserts in a transaction. If any fails, all roll back.','import sqlite3, pandas as pd\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE t (id INT PRIMARY KEY, name TEXT, rev REAL)")\ndf = pd.DataFrame({"id":[1,2,3],"name":["A","B","C"],"rev":[100,200,300]})\ndf.to_sql("t", conn, if_exists="replace", index=False)\nprint("Loaded:", conn.execute("SELECT COUNT(*) FROM t").fetchone()[0])','Full loader with verification.','import sqlite3\nimport pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\ndef create_schema(conn):\n    conn.execute("CREATE TABLE IF NOT EXISTS customers (id INT PRIMARY KEY, name TEXT, email TEXT, revenue REAL, loaded_at TEXT)")\n    conn.commit()\n\ndef load_batch(conn, df, batch=100):\n    loaded, errors = 0, 0\n    df = df.copy(); df["loaded_at"] = datetime.now().isoformat()\n    for s in range(0, len(df), batch):\n        b = df.iloc[s:s+batch]\n        try: b.to_sql("customers",conn,if_exists="append",index=False); loaded += len(b)\n        except Exception as e: print("Error at {}: {}".format(s,e)); errors += len(b)\n    return loaded, errors\n\nconn = sqlite3.connect(":memory:")\ncreate_schema(conn)\ndf = pd.DataFrame({"id":range(100),"name":["C{}".format(i) for i in range(100)],\n    "email":["c{}@ex.com".format(i) for i in range(100)],\n    "revenue":np.random.uniform(50,500,100).round(2)})\nloaded, errors = load_batch(conn, df)\ndb = conn.execute("SELECT COUNT(*) FROM customers").fetchone()[0]\nprint("Source:{} Loaded:{} Errors:{} DB:{} Match:{}".format(len(df),loaded,errors,db,"YES" if db==loaded else "NO"))',['Correct schema','Counts match','Timestamp added','Errors handled gracefully'],'A good loader is transactional.'),
  bi(5,'etl','ETL Processes','End-to-End ETL Pipeline',['Orchestrate complete pipeline','Handle failures with timing'],['Combine extract/transform/load','Add logging','Chain all stages','Time each stage','Test with failures','Add summary report'],'Log the stage name so you know where it failed.','import time\nfor stage in ["extract","transform","load"]:\n    s = time.time()\n    time.sleep(0.05)\n    print("[{}] {:.3f}s".format(stage, time.time()-s))','Full ETL with timing.','import pandas as pd, sqlite3, time, logging, numpy as np\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")\nlog = logging.getLogger("etl")\n\ndef run():\n    log.info("=== Start ===")\n    t = {}\n    \n    s = time.time()\n    np.random.seed(42)\n    raw = pd.DataFrame({"id":range(500),"name":["C{}".format(i) for i in range(500)],\n        "val":np.random.normal(100,30,500).round(2)})\n    raw.loc[10,"val"] = None; raw.loc[20,"name"] = None\n    t["extract"] = round(time.time()-s,3)\n    log.info("Extract: %d rows in %ss", len(raw), t["extract"])\n    \n    s = time.time()\n    clean = raw.dropna(subset=["name"]).fillna({"val":raw["val"].median()})\n    clean["tier"] = pd.cut(clean["val"],bins=[0,80,120,999],labels=["L","M","H"])\n    t["transform"] = round(time.time()-s,3)\n    log.info("Transform: %d->%d in %ss", len(raw), len(clean), t["transform"])\n    \n    s = time.time()\n    conn = sqlite3.connect(":memory:")\n    clean.to_sql("data",conn,index=False)\n    n = conn.execute("SELECT COUNT(*) FROM data").fetchone()[0]\n    t["load"] = round(time.time()-s,3)\n    log.info("Load: %d rows in %ss", n, t["load"])\n    \n    log.info("=== Done: %d->%d->%d in %.3fs ===", len(raw), len(clean), n, sum(t.values()))\n\nrun()',['Runs end-to-end','Timing per stage','Errors caught','Summary with counts'],'Production ETL logs everything and handles every failure.'),
  bi(1,'data-warehouse','Data Warehousing','Star Schema Design',['Design fact and dimension tables','Define grain'],['Choose a business process','Define grain: one row = what','List dimensions: who, what, when, where','List measures: quantity, revenue, cost','Draw the star','Add surrogate keys'],'The grain determines what questions you can answer.','fact = {"table":"fact_sales","measures":["qty","revenue","cost"],\n    "fkeys":["date_key","product_key","customer_key"]}\ndims = [{"table":"dim_date","attrs":["date","month","quarter","year"]},\n    {"table":"dim_product","attrs":["name","category","price"]}]\nprint("Fact: {} ({} measures)".format(fact["table"],len(fact["measures"])))\nfor d in dims: print("  ->",d["table"])','Complete star schema DDL.','import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.executescript("""\nCREATE TABLE dim_date (key INTEGER PRIMARY KEY AUTOINCREMENT, full_date TEXT, month INT, quarter INT, year INT);\nCREATE TABLE dim_product (key INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, category TEXT, price REAL);\nCREATE TABLE dim_customer (key INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, segment TEXT, region TEXT);\nCREATE TABLE fact_sales (id INTEGER PRIMARY KEY AUTOINCREMENT,\n    date_key INT REFERENCES dim_date(key),\n    product_key INT REFERENCES dim_product(key),\n    customer_key INT REFERENCES dim_customer(key),\n    qty INT, revenue REAL, cost REAL);\n""")\nconn.execute("INSERT INTO dim_product (name,category,price) VALUES (\'Widget\',\'Elec\',29.99)")\nconn.execute("INSERT INTO dim_customer (name,segment,region) VALUES (\'Corp\',\'Enterprise\',\'West\')")\nconn.execute("INSERT INTO dim_date (full_date,month,quarter,year) VALUES (\'2025-03-15\',3,1,2025)")\nconn.execute("INSERT INTO fact_sales (date_key,product_key,customer_key,qty,revenue,cost) VALUES (1,1,1,5,149.95,75)")\nconn.commit()\nr = conn.execute("SELECT d.full_date,p.name,c.name,f.qty,f.revenue FROM fact_sales f JOIN dim_date d ON f.date_key=d.key JOIN dim_product p ON f.product_key=p.key JOIN dim_customer c ON f.customer_key=c.key").fetchone()\nprint("Sale: {} to {} on {}, qty={}, rev={}".format(r[1],r[2],r[0],r[3],r[4]))',['1 fact + 3 dims','Grain defined','Surrogate keys','Star join works'],'Star schema: simple joins, fast queries, business-friendly.'),
  bi(2,'data-warehouse','Data Warehousing','Dimensional Modeling',['Build a bus matrix','Find conformed dimensions'],['List 3+ business processes','Map dimensions per process','Build bus matrix','Identify shared dimensions','Design date dimension','Document as DW roadmap'],'Conformed dimensions let you join facts across business processes.','import pandas as pd\nm = pd.DataFrame({"Date":["Y","Y","Y"],"Customer":["Y","Y",""],"Product":["Y","","Y"]},\n    index=["Sales","Support","Inventory"])\nprint(m)\nprint("Conformed:", [c for c in m.columns if (m[c]=="Y").sum()>=2])','Bus matrix with analysis.','import pandas as pd\n\nproc = {"Sales":["Date","Customer","Product","Store"],\n    "Inventory":["Date","Product","Warehouse","Supplier"],\n    "Support":["Date","Customer","Agent","Product"],\n    "Marketing":["Date","Customer","Campaign","Channel"]}\n\nall_d = sorted(set(d for ds in proc.values() for d in ds))\nmatrix = pd.DataFrame(index=proc.keys(), columns=all_d)\nfor p, ds in proc.items():\n    for d in all_d: matrix.loc[p,d] = "Y" if d in ds else ""\n\nprint("=== Bus Matrix ===")\nprint(matrix.to_string())\nprint("\\n=== Conformed ===")\nfor d in all_d:\n    n = (matrix[d]=="Y").sum()\n    if n >= 2:\n        users = [p for p in proc if d in proc[p]]\n        print("  {}: {} processes ({})".format(d, n, ", ".join(users)))',['3+ processes','2+ conformed dims','Date dim designed','Matrix documented'],'The bus matrix shows the big picture before any SQL.'),
  bi(3,'data-warehouse','Data Warehousing','Building a Star Schema in SQL',['Create and populate star schema','Write analytical queries'],['CREATE TABLE for 4 dims + 1 fact','Add indexes on foreign keys','Load: 365 dates, 50 products, 100 customers','Generate 5000 facts','Write 3 analytical queries','Verify totals'],'Index every FK in the fact table.','import sqlite3\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE d (id INT PRIMARY KEY, month INT)")\nconn.execute("CREATE TABLE f (date_id INT, rev REAL)")\nconn.execute("CREATE INDEX idx ON f(date_id)")\nconn.execute("INSERT INTO d VALUES (1,3)")\nconn.execute("INSERT INTO f VALUES (1,150)")\nprint(conn.execute("SELECT d.month,SUM(f.rev) FROM f JOIN d ON f.date_id=d.id GROUP BY d.month").fetchall())','Full star schema with 5000 rows.','import sqlite3, random\nfrom datetime import date, timedelta\n\nconn = sqlite3.connect(":memory:"); random.seed(42)\nconn.executescript("""\nCREATE TABLE dim_date (k INT PRIMARY KEY, dt TEXT, month INT, qtr INT);\nCREATE TABLE dim_prod (k INT PRIMARY KEY, name TEXT, cat TEXT, price REAL);\nCREATE TABLE dim_cust (k INT PRIMARY KEY, name TEXT, region TEXT);\nCREATE TABLE fact (id INTEGER PRIMARY KEY, dk INT, pk INT, ck INT, qty INT, rev REAL);\nCREATE INDEX i1 ON fact(dk); CREATE INDEX i2 ON fact(pk);\n""")\nfor i in range(365):\n    d = date(2025,1,1)+timedelta(days=i)\n    conn.execute("INSERT INTO dim_date VALUES (?,?,?,?)",(i+1,str(d),d.month,(d.month-1)//3+1))\nfor i in range(50):\n    conn.execute("INSERT INTO dim_prod VALUES (?,?,?,?)",(i+1,"P{}".format(i+1),random.choice(["E","C","F","H"]),round(random.uniform(10,200),2)))\nfor i in range(100):\n    conn.execute("INSERT INTO dim_cust VALUES (?,?,?)",(i+1,"C{}".format(i+1),random.choice(["N","S","E","W"])))\nfor _ in range(5000):\n    dk,pk,ck = random.randint(1,365),random.randint(1,50),random.randint(1,100)\n    q = random.randint(1,20)\n    p = conn.execute("SELECT price FROM dim_prod WHERE k=?",(pk,)).fetchone()[0]\n    conn.execute("INSERT INTO fact (dk,pk,ck,qty,rev) VALUES (?,?,?,?,?)",(dk,pk,ck,q,round(q*p*random.uniform(0.8,1),2)))\nconn.commit()\nprint("=== By Quarter ===")\nfor r in conn.execute("SELECT d.qtr,SUM(f.rev) FROM fact f JOIN dim_date d ON f.dk=d.k GROUP BY d.qtr"):\n    print("  Q{}: {:,.0f}".format(r[0],r[1]))\nprint("\\n=== Top 5 Products ===")\nfor r in conn.execute("SELECT p.name,SUM(f.rev) FROM fact f JOIN dim_prod p ON f.pk=p.k GROUP BY p.name ORDER BY 2 DESC LIMIT 5"):\n    print("  {}: {:,.0f}".format(r[0],r[1]))\nprint("\\n=== By Region ===")\nfor r in conn.execute("SELECT c.region,SUM(f.rev) FROM fact f JOIN dim_cust c ON f.ck=c.k GROUP BY c.region"):\n    print("  {}: {:,.0f}".format(r[0],r[1]))',['Indexes on FKs','5000+ facts loaded','3+ queries work','Star join pattern used'],'Well-indexed star schemas make complex questions into simple GROUP BYs.'),
  bi(4,'data-warehouse','Data Warehousing','OLAP Operations',['Perform slice, dice, drill, roll-up','Build pivot tables'],['Load star data','Slice: filter 1 dimension','Dice: filter 2 dimensions','Drill: yearly->quarterly->monthly','Roll up: daily->monthly','Pivot: region x category'],'Slice=filter one dim, Dice=filter multiple, Drill=add detail, Roll-up=remove detail.','import pandas as pd, numpy as np\ndf = pd.DataFrame({"date":pd.date_range("2025-01-01",periods=100),\n    "region":np.random.choice(["N","S","E","W"],100),\n    "cat":np.random.choice(["E","F"],100),\n    "rev":np.random.uniform(50,200,100)})\nprint(df.pivot_table(values="rev",index="region",columns="cat",aggfunc="sum").round(0))','Complete OLAP suite.','import pandas as pd, numpy as np\n\nnp.random.seed(42)\ndf = pd.DataFrame({"date":np.random.choice(pd.date_range("2025-01-01",periods=365),5000),\n    "region":np.random.choice(["N","S","E","W"],5000),\n    "cat":np.random.choice(["Elec","Cloth","Food","Home"],5000),\n    "rev":np.random.uniform(20,300,5000).round(2)})\ndf["month"] = df["date"].dt.month\ndf["qtr"] = df["date"].dt.quarter\n\nprint("=== SLICE: Q1 ===")\nq1 = df[df.qtr==1]\nprint("Q1: {:,.0f} ({} txns)".format(q1.rev.sum(), len(q1)))\n\nprint("\\n=== DICE: Q1+East ===")\ndice = df[(df.qtr==1)&(df.region=="E")]\nprint("{:,.0f} ({} txns)".format(dice.rev.sum(), len(dice)))\n\nprint("\\n=== DRILL: Year->Qtr ===")\nprint("Year: {:,.0f}".format(df.rev.sum()))\nfor q in sorted(df.qtr.unique()):\n    print("  Q{}: {:,.0f}".format(q, df[df.qtr==q].rev.sum()))\n\nprint("\\n=== ROLL UP: Monthly ===")\nprint(df.groupby("month")["rev"].agg(["sum","count"]).head().round(0))\n\nprint("\\n=== PIVOT ===")\nprint(df.pivot_table(values="rev",index="region",columns="cat",aggfunc="sum",margins=True).round(0))',['All 4 OLAP ops','Pivot shows 2 dims','3-level drill','Counts included'],'OLAP lets analysts explore interactively.'),
  bi(5,'data-warehouse','Data Warehousing','Query Optimization',['Use EXPLAIN and indexes','Create summary tables'],['Run complex query, time it','Use EXPLAIN QUERY PLAN','Add indexes on WHERE/JOIN cols','Re-run and compare','Create summary table','Document results'],'#1: Index JOIN/WHERE columns. #2: Pre-aggregate common queries.','import sqlite3, time\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE s (id INT, dk INT, rev REAL)")\nconn.execute("CREATE INDEX idx ON s(dk)")\nprint("Index created")','Query optimization with benchmarks.','import sqlite3, random, time\n\nconn = sqlite3.connect(":memory:"); random.seed(42)\nconn.execute("CREATE TABLE s (id INT PRIMARY KEY, dk INT, pk INT, rev REAL)")\nconn.execute("BEGIN")\nfor i in range(100000):\n    conn.execute("INSERT INTO s VALUES (?,?,?,?)",(i,random.randint(1,365),random.randint(1,500),round(random.uniform(10,500),2)))\nconn.execute("COMMIT")\n\nq = "SELECT dk,SUM(rev) FROM s WHERE pk BETWEEN 1 AND 50 GROUP BY dk"\n\nt1 = time.time()\nr1 = conn.execute(q).fetchall()\nt1 = time.time()-t1\nprint("No index: {:.4f}s ({} rows)".format(t1, len(r1)))\n\nconn.execute("CREATE INDEX idx_pk ON s(pk)")\nt2 = time.time()\nr2 = conn.execute(q).fetchall()\nt2 = time.time()-t2\nprint("With index: {:.4f}s".format(t2))\nprint("Speedup: {:.1f}x".format(t1/t2 if t2>0 else 0))\n\nconn.execute("CREATE TABLE summary AS SELECT dk,pk,SUM(rev) as total,COUNT(*) as n FROM s GROUP BY dk,pk")\nt3 = time.time()\nr3 = conn.execute("SELECT dk,SUM(total) FROM summary WHERE pk BETWEEN 1 AND 50 GROUP BY dk").fetchall()\nt3 = time.time()-t3\nprint("Summary: {:.4f}s".format(t3))',['EXPLAIN used','Index added','Measurable speedup','Summary table created'],'Fastest query reads the least data.'),
  bi(1,'report-automation','Report Automation','Report Templates',['Create reusable Jinja2 template','Parameterize dates and filters'],['Install jinja2','Design report structure','Create HTML template','Write render function','Add conditional sections','Test 3 date ranges'],'Jinja2 separates content from layout.','from jinja2 import Template\nt = Template("<h1>{{ title }}</h1><p>{{ start }} to {{ end }}</p>")\nprint(t.render(title="Report", start="2025-01-01", end="2025-01-31"))','Full report template system.','from jinja2 import Template\nfrom datetime import datetime\n\nt = Template("""<html><body style="background:#0b1d2a;color:#f8f9fb;padding:20px;font-family:Arial">\n<h1>{{ title }}</h1><p>{{ start }} to {{ end }} | {{ now }}</p>\n<div style="display:flex;gap:16px">\n{% for k in kpis %}<div style="background:#142a3b;padding:16px;border-radius:8px;flex:1">\n<div style="font-size:24px;font-weight:bold;color:{{ k.color }}">{{ k.value }}</div>\n<div>{{ k.name }}</div></div>{% endfor %}\n</div>\n{% if alerts %}<h3 style="color:#e63946">Alerts</h3>\n<ul>{% for a in alerts %}<li>{{ a }}</li>{% endfor %}</ul>{% endif %}\n</body></html>""")\n\nhtml = t.render(title="Weekly Report", start="2025-03-10", end="2025-03-16",\n    now=datetime.now().strftime("%Y-%m-%d"),\n    kpis=[{"name":"Revenue","value":"142K","color":"#2a9d8f"},{"name":"Orders","value":"1240","color":"#2a9d8f"}],\n    alerts=["Avg order value down 8%"])\nwith open("report.html","w") as f: f.write(html)\nprint("Generated report.html ({} bytes)".format(len(html)))',['Renders without errors','Dates parameterized','Conditional sections work','Valid HTML'],'Template once, generate forever.'),
  bi(2,'report-automation','Report Automation','Automated Data Refresh',['Dynamic date-range queries','Build refresh views'],['Write relative-date queries','Create SQL view for latest week','Parameterize daily/weekly/monthly','Add freshness check','Create refresh function','Log metadata'],'Never hardcode dates. Relative dates work tomorrow without changes.','from datetime import datetime, timedelta\ndef refresh(days=7):\n    cutoff = (datetime.now()-timedelta(days=days)).strftime("%Y-%m-%d")\n    print("Data from {} to today".format(cutoff))\nrefresh(7); refresh(30)','Dynamic refresh system.','import sqlite3, pandas as pd, numpy as np\nfrom datetime import datetime, timedelta\n\nnp.random.seed(42)\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE sales (id INT, date TEXT, region TEXT, rev REAL)")\nfor i in range(1000):\n    d = datetime(2025,1,1)+timedelta(days=np.random.randint(0,90))\n    conn.execute("INSERT INTO sales VALUES (?,?,?,?)",(i,d.strftime("%Y-%m-%d"),\n        np.random.choice(["N","S","E","W"]),round(np.random.uniform(50,300),2)))\nconn.commit()\n\ndef refresh(conn, period="weekly"):\n    days = {"daily":1,"weekly":7,"monthly":30}.get(period,7)\n    cutoff = (datetime.now()-timedelta(days=days)).strftime("%Y-%m-%d")\n    latest = conn.execute("SELECT MAX(date) FROM sales").fetchone()[0]\n    print("Latest: {} | Cutoff: {}".format(latest, cutoff))\n    df = pd.read_sql("SELECT * FROM sales WHERE date >= \'{}\'".format(cutoff), conn)\n    print("{}: {} rows".format(period, len(df)))\n    return df\n\nfor p in ["daily","weekly","monthly"]: refresh(conn, p)',['Relative dates used','Freshness check works','Same function for all periods','Results validated'],'Relative dates mean the report works tomorrow.'),
  bi(3,'report-automation','Report Automation','Python Report Generation',['Generate styled Excel with openpyxl','Create formatted output'],['Install openpyxl','Query data into DataFrame','Write to Excel','Add conditional formatting','Add chart','Verify file'],'Use ExcelWriter with openpyxl engine.','import pandas as pd\ndf = pd.DataFrame({"KPI":["Rev","Margin"],"Value":[250,65],"Target":[200,60]})\ndf["Status"] = df.apply(lambda r: "OK" if r.Value>=r.Target else "MISS", axis=1)\ndf.to_excel("report.xlsx", index=False)\nprint("Saved report.xlsx")','Styled Excel with chart.','import pandas as pd, numpy as np\nfrom openpyxl import load_workbook\nfrom openpyxl.styles import PatternFill, Font\nfrom openpyxl.chart import BarChart, Reference\n\nnp.random.seed(42)\ndata = pd.DataFrame({"Month":["Jan","Feb","Mar","Apr","May","Jun"],\n    "Revenue":np.random.uniform(180,280,6).round(0),\n    "Target":[200,210,220,230,240,250],\n    "Expenses":np.random.uniform(120,180,6).round(0)})\ndata["Profit"] = data["Revenue"]-data["Expenses"]\ndata["vs%"] = ((data["Revenue"]-data["Target"])/data["Target"]*100).round(1)\n\nf = "monthly.xlsx"\ndata.to_excel(f, index=False, sheet_name="Report")\nwb = load_workbook(f); ws = wb["Report"]\nfill = PatternFill(start_color="142a3b",end_color="142a3b",fill_type="solid")\nfor cell in ws[1]: cell.fill = fill; cell.font = Font(color="a8dadc",bold=True)\nfor row in range(2, ws.max_row+1):\n    c = ws.cell(row=row,column=6)\n    c.font = Font(color="2a9d8f" if c.value and c.value>=0 else "e63946", bold=True)\nch = BarChart(); ch.title = "Revenue vs Target"\nch.add_data(Reference(ws,min_col=2,max_col=3,min_row=1,max_row=ws.max_row),titles_from_data=True)\nws.add_chart(ch,"H2")\nwb.save(f)\nprint("Generated {}".format(f))',['File opens properly','Header styled','Conditional formatting works','Chart embedded'],'Automation turns 2-hour tasks into 2-second scripts.'),
  bi(4,'report-automation','Report Automation','Email Distribution',['Send reports with attachments','Build HTML email bodies'],['Configure SMTP from env vars','Compose HTML body with KPIs','Attach Excel report','Add error handling','Test distribution list','Log delivery'],'Store credentials in env vars, never in code.','from email.mime.text import MIMEText\nmsg = MIMEText("<h1>Report</h1><p>Revenue: 250K</p>", "html")\nmsg["Subject"] = "Weekly Report"\nmsg["To"] = "team@co.com"\nprint("Prepared: {} -> {}".format(msg["Subject"], msg["To"]))','Email sender with attachments.','from email.mime.multipart import MIMEMultipart\nfrom email.mime.text import MIMEText\nfrom email.mime.base import MIMEBase\nfrom email import encoders\nimport os\nfrom datetime import datetime\n\ndef send(to, subj, html, attach=None, dry=True):\n    msg = MIMEMultipart()\n    msg["Subject"] = subj\n    msg["From"] = os.environ.get("SMTP_FROM","reports@co.com")\n    msg["To"] = ", ".join(to)\n    msg.attach(MIMEText(html, "html"))\n    if attach and os.path.exists(attach):\n        with open(attach,"rb") as f:\n            part = MIMEBase("application","octet-stream")\n            part.set_payload(f.read())\n        encoders.encode_base64(part)\n        part.add_header("Content-Disposition","attachment; filename={}".format(os.path.basename(attach)))\n        msg.attach(part)\n    if dry: print("[DRY] To:{} Subj:{} Size:{}".format(msg["To"],subj,len(html)))\n    return True\n\nhtml = "<div style=\\"background:#0b1d2a;color:#f8f9fb;padding:20px\\"><h2>Weekly Report</h2><p>Revenue: 142K</p></div>"\nsend(["mgr@co.com","team@co.com"], "Weekly - {}".format(datetime.now().strftime("%b %d")), html, dry=True)',['Email sends/dry-run ok','HTML inline KPIs','Attachment encoded','Creds from env'],'Email is the last mile of reporting.'),
  bi(5,'report-automation','Report Automation','Self-Service Reporting with Streamlit',['Build Streamlit app for non-technical users','Add filters and export'],['Install streamlit','Create sidebar filters','Add date range and dropdown','Display KPI metrics','Add interactive charts','Add CSV download','Run: streamlit run app.py'],'st.sidebar for filters, st.metric for KPIs, st.download_button for export.','import streamlit as st\nst.title("Dashboard")\nregion = st.sidebar.selectbox("Region",["All","N","S","E","W"])\nst.metric("Revenue","142K","+12%")\nst.download_button("CSV","id,rev\\n1,100","data.csv")','Complete Streamlit dashboard.','import streamlit as st\nimport pandas as pd\nimport plotly.express as px\nimport numpy as np\n\nst.set_page_config(page_title="Dashboard", layout="wide")\nst.title("Self-Service Dashboard")\n\nnp.random.seed(42)\ndates = pd.date_range("2025-01-01",periods=90,freq="D")\ndf = pd.DataFrame({"date":np.repeat(dates,4),\n    "region":np.tile(["N","S","E","W"],90),\n    "rev":np.random.uniform(50,300,360).round(2),\n    "orders":np.random.randint(5,50,360)})\n\nst.sidebar.header("Filters")\ndr = st.sidebar.date_input("Dates",value=(dates[0],dates[-1]))\nreg = st.sidebar.multiselect("Regions",df.region.unique(),default=list(df.region.unique()))\nmask = (df.date>=pd.Timestamp(dr[0]))&(df.date<=pd.Timestamp(dr[1]))&(df.region.isin(reg))\nf = df[mask]\n\nc1,c2,c3 = st.columns(3)\nc1.metric("Revenue","{:,.0f}".format(f.rev.sum()))\nc2.metric("Orders","{:,}".format(f.orders.sum()))\nc3.metric("AOV","{:.2f}".format(f.rev.sum()/max(f.orders.sum(),1)))\n\nl,r = st.columns(2)\nwith l: st.plotly_chart(px.line(f.groupby("date")["rev"].sum().reset_index(),x="date",y="rev"),use_container_width=True)\nwith r: st.plotly_chart(px.bar(f.groupby("region")["rev"].sum().reset_index(),x="region",y="rev",color="region"),use_container_width=True)\nst.download_button("CSV",f.to_csv(index=False),"data.csv","text/csv")',['Runs without errors','Filters update everything','Download works','Non-technical users can operate'],'Self-service frees analysts for deeper work.'),
  bi(1,'stakeholder-comm','Stakeholder Communication','Know Your Audience',['Profile stakeholders','Adjust style per audience'],['List 3 stakeholder types','Document: role, goals, tech level, time','Map needs by audience','Create profile template','Rewrite insight 3 ways','Document style guide'],'Executives: 10 seconds. Managers: 1 minute. Analysts: 10 minutes.','audiences = {"CEO":{"format":"1 slide","focus":"revenue"},\n    "VP":{"format":"5 slides","focus":"trends"},\n    "Analyst":{"format":"notebook","focus":"methodology"}}\nfor role, p in audiences.items():\n    print("{}: {} on {}".format(role, p["format"], p["focus"]))','Audience framework.','class Profile:\n    def __init__(self, role, detail, fmt, focus, time):\n        self.role = role; self.detail = detail; self.fmt = fmt\n        self.focus = focus; self.time = time\n    def adapt(self, insight, metric, value, change):\n        if self.detail == "exec":\n            return "{}: {} is {} ({}).".format(insight, metric, value, change)\n        elif self.detail == "mgr":\n            return "Finding: {}\\n{}: {} ({})\\nAction: TBD".format(insight, metric, value, change)\n        return "Analysis: {}\\nMetric: {} = {}\\nChange: {}\\nMethod: TBD".format(insight, metric, value, change)\n\nfor p in [Profile("CEO","exec","1 slide","bottom line","30s"),\n          Profile("VP","mgr","5 slides","pipeline","5min"),\n          Profile("Analyst","tech","notebook","methodology","30min")]:\n    print("--- {} ({}) ---".format(p.role, p.time))\n    print(p.adapt("Churn accelerating","Monthly churn","4.2%","up 1.1pp"))\n    print()',['3 profiles documented','Same insight 3 ways','Exec version <=2 sentences','Tech includes methodology'],'Best analysts explain to anyone.'),
  bi(2,'stakeholder-comm','Stakeholder Communication','Data Storytelling',['Use situation-complication-resolution','Lead with insights'],['Choose a business question','Write Situation','Write Complication','Write Resolution','Add 3 data points each','Put Resolution FIRST','Test: recommendation by sentence 3'],'SCR: Situation, Complication, Resolution. For execs, flip: Resolution first.','def story(sit, comp, res, evidence):\n    out = "REC: {}\\nWHY: {}\\nCTX: {}\\n".format(res, comp, sit)\n    for e in evidence: out += "  - {}\\n".format(e)\n    return out\nprint(story("Q1 grew 12%","SMB churn doubled","Invest 200K in CS",\n    ["SMB=35% rev","Churn costs 180K/mo","CS saves 50 accts/qtr"]))','Data story framework.','class Story:\n    def __init__(self, title):\n        self.title = title; self.sit = ""; self.comp = ""; self.res = ""; self.ev = []\n    def context(self, s, c, r): self.sit=s; self.comp=c; self.res=r; return self\n    def evidence(self, point, metric): self.ev.append({"p":point,"m":metric}); return self\n    def render(self):\n        lines = ["== {} ==".format(self.title), ""]\n        lines.append("REC: {}".format(self.res))\n        lines.append("WHY: {}".format(self.comp))\n        lines.append("\\nDATA:")\n        for e in self.ev[:3]: lines.append("  - {} ({})".format(e["p"],e["m"]))\n        return "\\n".join(lines)\n\ns = Story("SMB Churn Crisis")\ns.context("Q1 grew 12% via Enterprise","SMB churn doubled to 4.2%, 2.1M at risk",\n    "Hire 3 CS managers, launch 90-day onboarding")\ns.evidence("Churn doubled","2.1% to 4.2%")\ns.evidence("CS reduces churn 60%","1.8% vs 4.2%")\ns.evidence("40% churn in first 90 days","cohort analysis")\nprint(s.render())',['SCR or pyramid structure','3 key data points','Actionable recommendation','Includes risks'],'Show the right data in the right order to drive a decision.'),
  bi(3,'stakeholder-comm','Stakeholder Communication','Presentation Design',['One insight per slide','Annotate, don\'t decorate'],['Extract insight from story','Create 5-slide outline','Each title IS the insight','Replace legends with annotations','Remove decorations','Add speaker notes','5-second test per slide'],'Slide title IS the insight. "Revenue declined 15%" is a title. "Q2 Analysis" is not.','slides = [\n    {"title":"SMB Churn Threatens 2.1M","type":"problem"},\n    {"title":"Churn Doubled in 2 Quarters","type":"evidence"},\n    {"title":"CS Reduces Churn 60%","type":"evidence"},\n    {"title":"Invest 200K for 10.5x Return","type":"recommendation"},\n]\nfor i, s in enumerate(slides,1):\n    print("Slide {} [{}]: {}".format(i, s["type"], s["title"]))','Slide outline generator.','class Deck:\n    def __init__(self, title): self.title = title; self.slides = []\n    def add(self, insight, stype, visual, notes):\n        self.slides.append({"t":insight,"type":stype,"v":visual,"n":notes}); return self\n    def render(self):\n        lines = ["=== {} ({} slides) ===".format(self.title, len(self.slides))]\n        for i, s in enumerate(self.slides, 1):\n            lines.append("\\n--- Slide {} [{}] ---".format(i, s["type"].upper()))\n            lines.append("Title: {}".format(s["t"]))\n            lines.append("Visual: {}".format(s["v"]))\n            for n in s["n"]: lines.append("  - {}".format(n))\n        return "\\n".join(lines)\n\nd = Deck("SMB Retention")\nd.add("SMB Churn Is Our Biggest Risk","problem","Line chart with annotation at 4.2%",\n    ["Doubled in 2 quarters","2.1M at risk"])\nd.add("CS Reduces Churn 60%","evidence","Side-by-side: 1.8% vs 4.2%",\n    ["Model proven with Enterprise","SMB gets zero outreach"])\nd.add("200K Investment Protects 2.1M","rec","ROI waterfall",\n    ["10.5x return","5-week payback"])\nprint(d.render())',['Titles state insights','1 chart per slide','Annotations over legends','Speaker notes included'],'Each slide is one beat in a persuasive argument.'),
  bi(4,'stakeholder-comm','Stakeholder Communication','Handling Tough Questions',['Prepare for challenges','Use acknowledge-bridge-respond'],['Anticipate 5 likely questions','Prepare: answer, data, follow-up','Practice bridge phrases','Prepare backup slides','Create limitations section','Role-play challenges'],'Never guess. "I will get that to you by EOD" beats a wrong answer.','qa = [\n    {"q":"How confident in the forecast?","a":"80% CI: 2.1M-2.5M","backup":"Slide 12"},\n    {"q":"Why SMB different from Enterprise?","a":"No CS coverage","backup":"Slide 8"},\n]\nfor item in qa:\n    print("Q: {}".format(item["q"]))\n    print("A: {}\\n".format(item["a"]))','Q&A prep framework.','class QAKit:\n    def __init__(self, topic): self.topic = topic; self.qs = []; self.lims = []\n    def add_q(self, q, a, ev, fu=None):\n        self.qs.append({"q":q,"a":a,"ev":ev,"fu":fu}); return self\n    def add_lim(self, l, m):\n        self.lims.append({"l":l,"m":m}); return self\n    def render(self):\n        lines = ["=== Q&A: {} ===".format(self.topic)]\n        for i, q in enumerate(self.qs, 1):\n            lines.append("\\nQ{}: {}".format(i, q["q"]))\n            lines.append("  A: {}".format(q["a"]))\n            lines.append("  Evidence: {}".format(q["ev"]))\n            if q["fu"]: lines.append("  Follow-up: {}".format(q["fu"]))\n        if self.lims:\n            lines.append("\\n=== Limitations ===")\n            for l in self.lims: lines.append("  {} -> {}".format(l["l"],l["m"]))\n        return "\\n".join(lines)\n\nk = QAKit("SMB Retention")\nk.add_q("How do we know CS works vs selection bias?",\n    "Controlled pilot: matched cohorts, 60% reduction","p < 0.01","Full report by Friday")\nk.add_q("Why not reduce pricing?",\n    "72% cite onboarding confusion, 18% cite price","Exit survey (500 respondents)")\nk.add_lim("6-month data window","Re-validate after Q3")\nprint(k.render())',['5+ questions prepared','Evidence for each','Follow-up commitments','Limitations documented'],'Confidence comes from preparation.'),
  bi(5,'stakeholder-comm','Stakeholder Communication','Written Reports',['Pyramid principle executive summary','Report with methodology appendix'],['Start with recommendation','Add 3 evidence points','Write methodology paragraph','State assumptions','Add Next Steps with owners','Move detail to appendix','Test: key message in first paragraph'],'Pyramid: conclusion first, then evidence in decreasing importance.','sections = ["1. Executive Summary","2. Recommendation","3. Evidence (3 sections)",\n    "4. Risks","5. Next Steps","6. Appendix: Methodology"]\nfor s in sections: print(s)','Executive report generator.','from datetime import datetime\n\ndef report(title, author, rec, evidence, risks, steps, method):\n    lines = ["="*50, title, "By {} | {}".format(author, datetime.now().strftime("%Y-%m-%d")), "="*50, ""]\n    lines.append("EXECUTIVE SUMMARY\\n" + "-"*30)\n    lines.append("Action: {}".format(rec["action"]))\n    lines.append("Cost: {}  Return: {}".format(rec["cost"], rec["ret"]))\n    lines.append("\\nEVIDENCE\\n" + "-"*30)\n    for i, e in enumerate(evidence, 1):\n        lines.append("{}. {} ({})".format(i, e["finding"], e["metric"]))\n        lines.append("   So what: {}".format(e["impl"]))\n    lines.append("\\nRISKS\\n" + "-"*30)\n    for r in risks: lines.append("  {} -> {}".format(r["risk"], r["mit"]))\n    lines.append("\\nNEXT STEPS\\n" + "-"*30)\n    for s in steps: lines.append("  [ ] {} - {} - {}".format(s["action"],s["owner"],s["due"]))\n    lines.append("\\n" + "="*50 + "\\nAPPENDIX: " + method)\n    return "\\n".join(lines)\n\nprint(report("SMB Retention Strategy", "BI Team",\n    {"action":"Hire 3 CS Managers","cost":"200K/yr","ret":"2.1M protected (10.5x)"},\n    [{"finding":"Churn doubled","metric":"2.1% to 4.2%","impl":"2.1M at risk"},\n     {"finding":"CS reduces churn 60%","metric":"1.8% vs 4.2%","impl":"Proven model"},\n     {"finding":"40% churn in 90 days","metric":"cohort","impl":"Onboarding is key"}],\n    [{"risk":"Hiring takes 2-3mo","mit":"Use existing CS for top-50 now"}],\n    [{"action":"Approve headcount","owner":"VP Sales","due":"This week"},\n     {"action":"Prioritize accounts","owner":"BI","due":"Friday"}],\n    "6 months churn data. Matched cohorts. p < 0.01."))',['Leads with recommendation','3 evidence points with implications','Risks with mitigations','Methodology in appendix'],'A great report: reader knows what to do after the first paragraph.'),
];
